package com.disasterinfo.eodiisseo.disaster.collection;
import com.disasterinfo.eodiisseo.collection.execution.CollectionProviderPort.*;import tools.jackson.databind.json.JsonMapper;
import org.junit.jupiter.api.Test;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.ValueSource;
import java.time.*;import java.util.*;import java.math.BigInteger;import java.nio.charset.StandardCharsets;import static org.junit.jupiter.api.Assertions.*;
/** Synthetic protocol checks, no official incident, timezone or incremental guarantee. */
class MoisMessagesContractTest {
 final Request request=new Request(LocalDate.of(2026,11,1),LocalDate.of(2026,11,1),1,2,Duration.ofSeconds(2));
 OfficialCollectionProviderPlugin messages(){return new OfficialCollectionProviderPlugin("MOIS_MESSAGES",(c,r)->{throw new AssertionError("No HTTP");});}
 Map<String,Object> body(int count,List<Map<String,Object>> rows){return new LinkedHashMap<>(Map.of("header",Map.of("resultCode","00"),"totalCount",count,"body",rows));}
 Reply reply(Map<String,Object> envelope){return new Reply(200,JsonMapper.builder().build().writeValueAsBytes(envelope),Duration.ZERO);}
 @ParameterizedTest @ValueSource(strings={"DUPLICATE","TRAILING"}) void ambiguousJsonCannotChooseAnIdentityOrCount(String kind){String s=new String(reply(body(1,List.of(Map.of("SN","A")))).body(),StandardCharsets.UTF_8);s=kind.equals("DUPLICATE")?s.replace("\"SN\":\"A\"","\"SN\":\"B\",\"SN\":\"A\""):s+"{}";var wire=new Reply(200,s.getBytes(StandardCharsets.UTF_8),Duration.ZERO);assertThrows(InvalidResponse.class,()->messages().decode(wire,request));}
 @ParameterizedTest @ValueSource(ints={0,1}) void rowsCannotReplaceAnInconsistentTotal(int total){assertThrows(InvalidResponse.class,()->messages().decode(reply(body(total,List.of(Map.of("SN","A"),Map.of("SN","B")))),request));}
 @ParameterizedTest @ValueSource(strings={"BOOLEAN","OBJECT","ARRAY","DECIMAL","MISSING","CONTROL"}) void unstableIdShapesCannotBecomeStableMessageKeys(String shape){var row=new LinkedHashMap<String,Object>();Object id=switch(shape){case "BOOLEAN"->true;case "OBJECT"->Map.of("id","A");case "ARRAY"->List.of("A");case "DECIMAL"->1.25;case "CONTROL"->"A\nB";default->null;};if(id!=null)row.put("SN",id);assertThrows(InvalidResponse.class,()->messages().decode(reply(body(1,List.of(row))),request));}
 @ParameterizedTest @ValueSource(strings={"PAGE","ZERO_ROWS","LARGE_ROWS","MISSING_TOTAL"}) void declaredMetadataIsCheckedWithoutInventingEchoRequirements(String scenario){var b=body(1,List.of(Map.of("SN","A")));switch(scenario){case "PAGE"->b.put("pageNo",2);case "ZERO_ROWS"->b.put("numOfRows",0);case "LARGE_ROWS"->b.put("numOfRows",3);default->b.remove("totalCount");}assertThrows(InvalidResponse.class,()->messages().decode(reply(b),request));}
 @Test void absentEchoAndUnknownDateStringsArePreservedAsUnverifiedRawFacts(){for(String date:List.of("2026/11/01 10:00:00.123456789","2026/02/30 24:00:00","UNKNOWN")){var row=Map.<String,Object>of("SN","0000000000000000000001","CRT_DT",date,"REG_YMD",date,"MDFCN_YMD",date,"RCPTN_RGN_NM","SYNTHETIC recipient only");assertEquals(row,messages().decode(reply(body(1,List.of(row))),request).items().getFirst());}assertFalse(messages().evidence().incremental());}
 @Test void largeIntegralIdsAndLeadingZerosRemainExactAndDistinct(){for(Object id:List.of(new BigInteger("9999999999999999999999"),"0000000000000000000001")){var page=messages().decode(reply(body(1,List.of(Map.of("SN",id)))),request);assertEquals(id.toString(),messages().identity(page.items().getFirst()));}}
 @Test void shelterDecoderDoesNotAcquireMessageIdentityOrNewValidationPolicy(){var shelter=new OfficialCollectionProviderPlugin("MOIS_SHELTERS",(c,r)->{throw new AssertionError("No HTTP");});var row=Map.<String,Object>of("ARCD","A","ACMDFCLTY_SN","1");assertEquals(1,shelter.decode(reply(body(1,List.of(row))),request).items().size());}
 @Test void wildfireInfoRemainsIndependentDisabledAndUnlinkedEvenWithMatchingMessageText(){var calls=new java.util.concurrent.atomic.AtomicInteger();var fire=new OfficialCollectionProviderPlugin("MOIS_WILDFIRE",(c,r)->{calls.incrementAndGet();throw new AssertionError();});assertFalse(fire.executable());assertThrows(RuntimeException.class,()->fire.exchange(request));assertEquals(0,calls.get());var inspected=OfficialWildfireInfoInspector.inspect("DSSP-IF-10346",Map.of("FRSTFR_INFO_ID","A","SN","A","LINK_MSG_ID","A","LINK_STTS","1","EXTNGS_END_DT","2026/11/01 12:00:00"));assertEquals(OfficialWildfireInfoInspector.Decision.UNLINKED,inspected.decision());assertTrue(inspected.gaps().contains(OfficialWildfireInfoInspector.Gap.MESSAGE_ASSOCIATION));assertFalse(inspected.reviewFields().containsKey("SN"));}
}
